SELECT ILI_DATA_ID "ILI_DATA_ID", ABSOLUTE_ODOMETER "ABSOLUTE_ODOMETER", CALIBRATED_MEASURE "MEASURE", CONTROL_POINT_LF "CONTROL_POINT_LF", CERTAINTY_INTERVAL "ACCURACY", null "EVENT_ID" FROM sgio_ili_data d WHERE d.ili_inspection_id = {P_REPORT_ID} AND absolute_odometer IS NOT NULL order by absolute_odometer
WITH z_route as (SELECT id,GEOMETRY geom FROM pods_route), segments AS (SELECT id,ST_DumpPoints(ST_LineMerge(st_transform(l.geom,4326))) as p from z_route l where id={P_ROUTE_ID}), points AS (SELECT id,(p).path[1] AS point_index,(p).geom AS point_geom FROM segments), line_segments AS (SELECT p1.id, p1.point_index,ST_MakeLine(p1.point_geom, p2.point_geom) AS segment FROM points p1 JOIN points p2 ON p1.id = p2.id AND p1.point_index = p2.point_index - 1), segment_lengths AS (SELECT id, point_index,ST_Length(segment::geography) AS segment_length FROM line_segments), cumulative_lengths AS (SELECT id, point_index, segment_length, SUM(segment_length) OVER (PARTITION BY id ORDER BY point_index) AS cumulative_length FROM segment_lengths), pnt_meas as (SELECT p.id, p.point_index,ST_X(p.point_geom) AS x,ST_Y(p.point_geom) AS y, coalesce(cl.cumulative_length,0) cumulative_length FROM points p left JOIN cumulative_lengths cl ON cl.id = p.id AND cl.point_index+1 = p.point_index ORDER BY p.id, p.point_index), lin as (select ST_GeomFromText('Linestring m ('||string_agg(X||' '||Y||' '||cumulative_length, ',' order by cumulative_length)||')',4326) geom, id from pnt_meas group by id), arr_points as (SELECT ST_InterpolatePoint((select geom from lin), m.geom) measure, ST_LineInterpolatePoint((select geom from lin), ST_LineLocatePoint((select geom from lin), m.geom)) geom, m.station_id id, m.station, 'marker' cls from pods_marker m where ST_within(m.geom,(select st_buffer(geom::geography,10)::geometry geo from lin)) union all SELECT ST_InterpolatePoint((select geom from lin), (ST_Dump(st_transform(s.geom,4326))).geom) measure, ST_LineInterpolatePoint((select geom from lin), ST_LineLocatePoint((select geom from lin), (ST_Dump(st_transform(s.geom,4326))).geom)) geom, id+1000000 id, 999 /*nullif(s."KM_CONNECT",'')::numeric*/ station, 'valve' cls FROM pods_valve s where ST_within(st_transform(s.geom,4326),(select st_buffer(geom::geography,1)::geometry geo from lin)) union all select calibrated_measure "MEASURE",ST_GeomFromText('POINT('||X_COORD||' '||Y_COORD||')', 4326) geom, ili_data_id id, station "STATION",'valve' cls from sgio_ili_data d where d.ili_inspection_id={P_REPORT_ID} and REF_EVENT_ID=-999 union all SELECT ST_M((dp).geom) measure ,(dp).geom,(dp).path[1] id, null station, 'point' cls FROM ( SELECT ST_DumpPoints(st_transform(l.geom,4326)) AS dp FROM lin l ) AS dump_points) select S.measure "MEASURE", S.STATION "STATION", 50 "LINE_ID", 50 "ROUTE_ID", 50 "SERIES_ID", 50 "SERIES", id "STATION_ID", 0 "DEPTH", null "SRV_DISTRICT_GCL", id "COORDINATE_ID", id "LOCATION_ID", st_x(geom) "X", st_y(geom) "Y", null "Z" from arr_points s order by s.measure
DO $$
DECLARE sp_id NUMERIC(16,0); loc_id NUMERIC(16,0); c_id NUMERIC(16,0); e_id NUMERIC(16,0); BEGIN
UPDATE sgio_ili_data SET CALIBRATED_MEASURE = {MEASURE}, srv_district_gcl = {SRV_DISTRICT_GCL}, x_coord = {X}, y_coord = {Y}, z_coord = {Z}, tube_height = {DEPTH}, station = {STATION}, pipe_measure = {MEASURE} WHERE ili_data_id = {ILI_DATA_ID}; END $$;
DO $$ DECLARE km NUMERIC(10,2); lc NUMERIC(10,2); BEGIN DELETE FROM WEB50.PS_INDEX_OBJ WHERE KEY_VALUES = '{src_id}';
SELECT sp1.measure+{fract}*(sp2.measure-sp1.measure),sp1.station+{fract}*(sp2.station-sp1.station) INTO lc,km FROM pods.station_point sp1, pods.station_point sp2 WHERE sp1.station_id = {s_id} AND sp2.station_id = {e_id};
INSERT INTO WEB50.PS_INDEX_OBJ(TEMPLATE_ID, PIPE_SYSTEM_ID, STATE_ID, KEY_FIELDS, KEY_VALUES, KM_START, KM_END, LINE_COORD_START, LINE_COORD_END, DISTANCE, GID, CUSER_ID) VALUES(1, {id}, 0, 'ILI_DATA_ID', '{src_id}', km, km, lc, lc, {dist}, NULL, 0); END $$;
SELECT p.ILI_PIPE_LENGTH_ID "ILI_PIPE_LENGTH_ID", p.WELD_NUMBER "WELD_NUMBER", null "EVENT_ID", d1.x_coord "X_COORD", d1.y_coord "Y_COORD", d1.DS_WELD_DISTANCE "ODOM_LENGTH", d2.pipe_MEASURE-d1.pipe_MEASURE "LENGTH", d2.x_coord "NEXT_X_COORD", d2.y_coord "NEXT_Y_COORD" from sgio_ili_pipe_length p join sgio_ili_data d1 on p.ili_inspection_id = d1.ili_inspection_id and p.weld_number = d1.weld_number and d1.anomaly_type_cl = 5001 join sgio_ili_data d2 on p.ili_inspection_id = d2.ili_inspection_id and p.weld_number = d2.us_weld_number and d2.anomaly_type_cl = 5001 where p.ili_inspection_id = {P_REPORT_ID} order by d1.absolute_odometer
/*10.10.25: это больше не нужно надо удалить вызов*/ select null res;
UPDATE sgio_ili_pipe_length SET x_coord_start = {X_COORD}, y_coord_start = {Y_COORD}, x_coord_end = {NEXT_X_COORD}, y_coord_end = {NEXT_Y_COORD} WHERE ILI_PIPE_LENGTH_ID = {ILI_PIPE_LENGTH_ID}
/*10.10.25: это больше не нужно надо удалить вызов*/ select null res;
/*10.10.25: это больше не нужно надо удалить вызов*/ select null res;
/*10.10.25: это больше не нужно надо удалить вызов*/ select null res; /*UPDATE sgio_ili_data set srv_district_gcl = null, x_coord = null, y_coord = null, z_coord = null, tube_height = null, station = null, pipe_measure = null, ref_event_id = null, control_point_lf = 'N', calibrated_measure = null, certainty_interval = null WHERE ili_inspection_id = {P_REPORT_ID} and control_point_lf = 'N' */
/*10.10.25: это больше не нужно надо удалить вызов*/ select null res; /* UPDATE sgio_ili_pipe_length set event_id = null, x_coord_start = null, y_coord_start = null, x_coord_end = null, y_coord_end = null WHERE ili_inspection_id = {P_REPORT_ID} */
/*10.10.25: это больше не нужно надо удалить вызов*/ select null res;
/*10.10.25: это больше не нужно надо удалить вызов*/ select null res;
