SELECT ili_data_id "OBJ_ID", absolute_odometer "LINE_COORD", CASE WHEN d.anomaly_type_cl IN (1003,1007,1008) THEN '1' WHEN d.anomaly_type_cl=1004 THEN '2' END "OBJ_CLS_ID" FROM sgio_ili_data d WHERE d.ili_inspection_id = {P_REPORT_ID} AND d.anomaly_type_cl IN (1003,1004,1007,1008) ORDER BY absolute_odometer
WITH z_route as (SELECT id,GEOMETRY geom FROM pods_route), segments AS (SELECT id,ST_DumpPoints(ST_LineMerge(st_transform(l.geom,4326))) as p from z_route l where id={P_ROUTE_ID}), points AS (SELECT id,(p).path[1] AS point_index,(p).geom AS point_geom FROM segments), line_segments AS (SELECT p1.id, p1.point_index,ST_MakeLine(p1.point_geom, p2.point_geom) AS segment FROM points p1 JOIN points p2 ON p1.id = p2.id AND p1.point_index = p2.point_index - 1), segment_lengths AS (SELECT id, point_index,ST_Length(segment::geography) AS segment_length FROM line_segments), cumulative_lengths AS (SELECT id, point_index, segment_length, SUM(segment_length) OVER (PARTITION BY id ORDER BY point_index) AS cumulative_length FROM segment_lengths), pnt_meas as (SELECT p.id, p.point_index,ST_X(p.point_geom) AS x,ST_Y(p.point_geom) AS y, coalesce(cl.cumulative_length,0) cumulative_length FROM points p left JOIN cumulative_lengths cl ON cl.id = p.id AND cl.point_index+1 = p.point_index ORDER BY p.id, p.point_index), lin as (select ST_GeomFromText('Linestring m ('||string_agg(X||' '||Y||' '||cumulative_length, ',' order by cumulative_length)||')',4326) geom, id from pnt_meas group by id), arr_points as (SELECT ST_InterpolatePoint((select geom from lin), m.geom) measure, ST_LineInterpolatePoint((select geom from lin), ST_LineLocatePoint((select geom from lin), m.geom)) geom, m.station_id id, m.station, '2' cls from sgio_ngg_marker m where ST_within(m.geom,(select st_buffer(geom::geography,10)::geometry geo from lin)) union all SELECT ST_InterpolatePoint((select geom from lin), (ST_Dump(st_transform(s.geom,4326))).geom) measure, ST_LineInterpolatePoint((select geom from lin), ST_LineLocatePoint((select geom from lin), (ST_Dump(st_transform(s.geom,4326))).geom)) geom, id+1000000 id, 999 /*nullif(s."KM_CONNECT",'')::numeric*/ station, '1' cls FROM pods_valve s where ST_within(st_transform(s.geom,4326),(select st_buffer(geom::geography,1)::geometry geo from lin)) union all SELECT calibrated_measure measure, ST_GeomFromText('POINT('||x_coord||' '||y_coord||')', 4326) geom, ref_event_id id, station, '1' obj_cls_id FROM sgio_ili_data d where d.ili_inspection_id={P_REPORT_ID} and ref_event_id=-999 and calibrated_measure is not null ) select id "OBJ_ID", S.measure "LINE_COORD", cls "OBJ_CLS_ID" from arr_points s order by s.measure
WITH z_route as (SELECT id,GEOMETRY geom FROM pods_route), segments AS (SELECT id,ST_DumpPoints(ST_LineMerge(st_transform(l.geom,4326))) as p from z_route l where id={P_ROUTE_ID}), points AS (SELECT id,(p).path[1] AS point_index,(p).geom AS point_geom FROM segments), line_segments AS (SELECT p1.id, p1.point_index,ST_MakeLine(p1.point_geom, p2.point_geom) AS segment FROM points p1 JOIN points p2 ON p1.id = p2.id AND p1.point_index = p2.point_index - 1), segment_lengths AS (SELECT id, point_index,ST_Length(segment::geography) AS segment_length FROM line_segments), cumulative_lengths AS (SELECT id, point_index, segment_length, SUM(segment_length) OVER (PARTITION BY id ORDER BY point_index) AS cumulative_length FROM segment_lengths), pnt_meas as (SELECT p.id, p.point_index,ST_X(p.point_geom) AS x,ST_Y(p.point_geom) AS y, coalesce(cl.cumulative_length,0) cumulative_length FROM points p left JOIN cumulative_lengths cl ON cl.id = p.id AND cl.point_index+1 = p.point_index ORDER BY p.id, p.point_index), lin as (select ST_GeomFromText('Linestring m ('||string_agg(X||' '||Y||' '||cumulative_length, ',' order by cumulative_length)||')',4326) geom, id from pnt_meas group by id), arr_points as (SELECT ST_InterpolatePoint((select geom from lin), m.geom) measure, ST_LineInterpolatePoint((select geom from lin), ST_LineLocatePoint((select geom from lin), m.geom)) geom, m.station_id id, m.station, '2' cls from pods_marker m where ST_within(m.geom,(select st_buffer(geom::geography,10)::geometry geo from lin)) union all SELECT ST_InterpolatePoint((select geom from lin), (ST_Dump(st_transform(s.geom,4326))).geom) measure, ST_LineInterpolatePoint((select geom from lin), ST_LineLocatePoint((select geom from lin), (ST_Dump(st_transform(s.geom,4326))).geom)) geom, id+1000000 id, 999 /*nullif(s."KM_CONNECT",'')::numeric*/ station, '1' cls FROM pods_valve where ST_within(st_transform(s.geom,4326),(select st_buffer(geom::geography,1)::geometry geo from lin))) UPDATE sgio_ili_data SET (ref_event_id, control_point_lf, calibrated_measure, certainty_interval) = ( SELECT id, 'Y', measure, {COEFF} FROM arr_points WHERE id = {FACILITY_ID}) WHERE ili_data_id = {REPER_ID} and coalesce(ref_event_id,0)<>-999
UPDATE sgio_ili_data SET ref_event_id = null, control_point_lf = 'N', calibrated_measure = null, certainty_interval = null WHERE ili_inspection_id = {P_REPORT_ID} and coalesce(ref_event_id,0)<>-999
SELECT ROUTE_ID "ROUTE_ID" FROM sgio_ili_inspection i WHERE ILI_INSPECTION_ID = {INSPECTION_ID}
SELECT ROUTE_ID "ROUTE_ID" FROM sgio_ili_inspection i WHERE ILI_INSPECTION_ID = {db_command.CMD.ILI_INSPECTION_ID}
UPDATE sgio_ili_data dst SET anomaly_extension_cl = coalesce((SELECT a.code FROM sgio_anomaly_extension_cl a JOIN sgio_ili_anomaly_type_cl b ON a.code = b.index_description WHERE b.code = dst.anomaly_type_cl),'UNKNOWN') WHERE dst.ili_inspection_id = {db_command.CMD.ILI_INSPECTION_ID}
DO $$ BEGIN update sgio_ili_data set weld_number=null where weld_number like '' and ili_inspection_id = {db_command.CMD.ILI_INSPECTION_ID};
update sgio_ili_data d set us_weld_distance=d.absolute_odometer-d.us_weld_odometer ,ds_weld_distance=d.ds_weld_odometer - d.absolute_odometer where EXISTS (select 1 from sgio_ili_data ddd JOIN sgio_ili_data ww ON ww.ili_inspection_id = ddd.ili_inspection_id AND ddd.absolute_odometer>=ww.absolute_odometer AND ww.absolute_odometer>=ddd.absolute_odometer-100 WHERE ww.ili_inspection_id = {db_command.CMD.ILI_INSPECTION_ID} AND ww.anomaly_type_cl = 5001 AND ddd.ili_data_id = d.ili_data_id);
END $$;
DO $$ BEGIN
update sgio_ili_data set weld_number=null where weld_number like '' and ili_inspection_id = {db_command_err.CMD.ILI_INSPECTION_ID};
update sgio_ili_data d set us_weld_distance=d.absolute_odometer-d.us_weld_odometer ,ds_weld_distance=d.ds_weld_odometer - d.us_weld_odometer + d.absolute_odometer - d.us_weld_odometer where EXISTS (select 1 from sgio_ili_data ddd JOIN sgio_ili_data ww ON ww.ili_inspection_id = ddd.ili_inspection_id AND ddd.absolute_odometer>=ww.absolute_odometer AND ww.absolute_odometer>=ddd.absolute_odometer-100 WHERE ww.ili_inspection_id = {db_command_err.CMD.ILI_INSPECTION_ID} AND ddd.weld_number is null AND ww.anomaly_type_cl = 5001 AND ddd.ili_data_id = d.ili_data_id);
END $$;
insert into sgio_ili_pipe_length(ili_inspection_id, weld_number, sequence_number, start_odometer, end_odometer, measured_wall_thickness, nominal_wall_thickness, source_gcl) select ili_inspection_id, weld_number, row_number() over(order by absolute_odometer), absolute_odometer, lead(absolute_odometer) over(order by absolute_odometer), measured_wall_thickness, nominal_wall_thickness, source_gcl from sgio_ili_data d where ili_inspection_id = {db_command.CMD.ILI_INSPECTION_ID} and anomaly_type_cl = 5001
insert into sgio_ili_pipe_length(ili_inspection_id, weld_number, sequence_number, start_odometer, end_odometer, measured_wall_thickness, nominal_wall_thickness, source_gcl) select ili_inspection_id, weld_number, row_number() over(order by absolute_odometer), absolute_odometer, lead(absolute_odometer) over(order by absolute_odometer), measured_wall_thickness, nominal_wall_thickness, source_gcl from sgio_ili_data d where ili_inspection_id = {db_command_err.CMD.ILI_INSPECTION_ID} and anomaly_type_cl = 5001
SELECT coalesce(MIN(route_id),0) "ROUTE_ID" FROM (SELECT s.route_id, min(s.station_begin) min_km, max(s.station_end) max_km FROM pods.line l JOIN pods.series s ON s.line_id = l.line_id WHERE UPPER(REGEXP_REPLACE(REPLACE(REPLACE(REPLACE(l.description,'III','3'),'II','2'),'I','1'),'\s|-|\(|\)','')) LIKE TRIM(UPPER(REGEXP_REPLACE(REPLACE(REPLACE(REPLACE('{PIPE}','III','3'),'II','2'),'I','1'),'\s|-|\(|\)',''))) GROUP BY s.route_id) dd WHERE ABS(min_km-{KM_START})<15 AND ABS(max_km-{KM_END})<15
DO $$ DECLARE RETURNiliid integer; RETURNeventid integer default -50; v_pipe varchar(50) default 'Объект лежит не на оси трубопровода'; BEGIN select l.description from pods.line l, pods.route r where r.route_id = {ROUTE_ID} and l.line_id = r.line_id into v_pipe;
INSERT INTO sgio_ILI_INSPECTION(BEGIN_DATE, END_DATE, TOOL_TYPE_CL, MODEL, ILI_COMMENTS, TOOL_VENDOR_CL, DESCRIPTION, "comments" ,route_id) VALUES (TO_DATE('{DATE}','DD.MM.YYYY'), TO_DATE('{DATE}','DD.MM.YYYY'), 'UNKNOWN', '{MODEL}', '{FORMAT}', '{COMPANY}', '{KM_START}-{KM_END}',v_pipe, {ROUTE_ID}) RETURNING ili_inspection_id INTO RETURNiliid; END $$;
DO $$
DECLARE v_coordinate_id NUMERIC(16); v_report_vendor VARCHAR(254); v_coordinate_source_operator VARCHAR(16); v_coordinate_source_id NUMERIC(16); v_year VARCHAR(4); v_location_id NUMERIC(16);
BEGIN INSERT INTO sgio_ILI_DATA(ILI_INSPECTION_ID,WELD_NUMBER,ABSOLUTE_ODOMETER,AVERAGE_DEPTH,LENGTH,WIDTH,INTERNAL_EXTERNAL_CL,SOURCE_GCL,DATE_COLLECTED, ORIENTATION_DEG,ANOMALY_TYPE_CL,ANOMALY_EXTENSION_CL,MEASURED_WALL_THICKNESS, FEATURE_DESCRIPTION,DESCRIPTION,MILEPOST,NOMINAL_WALL_THICKNESS, COMMENTS,US_WELD_ODOMETER,DS_WELD_ODOMETER,US_WELD_NUMBER,srv_district_gcl,x_coord,y_coord) VALUES({ILI_INSPECTION_ID},'{WELD_NUMBER}',NULLIF(replace('{ABSOLUTE_ODOMETER}',',','.'),'')::numeric,NULLIF(replace('{AVERAGE_DEPTH}',',','.'),'')::numeric, NULLIF(replace('{LENGTH}',',','.'),'')::numeric, NULLIF(replace('{WIDTH}',',','.'),'')::numeric, 'UNKNOWN','{SOURCE_GCL}',TO_DATE('{DATE}','DD.MM.YYYY'),ROUND(NULLIF(replace('{ORIENTATION_DEG}',',','.'),'')::numeric) ,CASE WHEN '{SOURCE}'='WLD' THEN 5001 ELSE (SELECT MIN(CODE) FROM sgio_ili_anomaly_type_cl t WHERE upper(','||coalesce(t.description,'')::text || ',' || coalesce(t.anomaly_references,'')::text) LIKE '%'||REGEXP_REPLACE (UPPER (TRIM ('{ANOMALY_TYPE_CL}')),'\(.*\)|[*.?]|\s+','%')|| '%') END ,'UNKNOWN',NULL,'{FEATURE_DESCRIPTION}','{DESCRIPTION}','{MILEPOST}',NULLIF(replace('{NOMINAL_WALL_THICKNESS}',',','.'),'')::numeric, '{COMMENTS}',NULLIF(replace('{US_WELD_ODOMETER}',',','.'),'')::numeric,NULLIF(replace('{DS_WELD_ODOMETER}',',','.'),'')::numeric, NULLIF(replace('{US_WELD_NUMBER}',',','.'),'')::numeric, {SRV_DISTRICT_GCL},NULLIF(replace('{X}',',','.'),'')::numeric,NULLIF(replace('{Y}',',','.'),'')::numeric);
END $$;
SELECT CODE "CODE" ,UPPER(description) ||CASE WHEN ANOMALY_REFERENCES IS NOT NULL THEN ','|| UPPER(ANOMALY_REFERENCES) ELSE '' END "EXTENDED_DESCRIPTION" FROM sgio_ili_anomaly_type_cl
